select FT.BankID, FT.BankName, FT.BankBranchID, FT.BankBranchName ,FT.BankAccountID, FT.BankAccountNumber, FT.BankAccountName , SUM(FT.TotOpeningBalance) TotOpeningBalance from (
Select Distinct AR_Set_bank.BankID,UPPER(AR_Set_bank.BankName) AS BankName, AR_SET_BankBranch.BankBranchID,UPPER(AR_SET_BankBranch.BankBranchName) AS BankBranchName, AR_Set_bankAccount.BankAccountID, AR_Set_bankAccount.BankAccountNumber,UPPER(AR_Set_bankAccount.BankAccountName) AS BankAccountName, 0 As TotOpeningBalance From AR_Set_bankAccount INNER JOIN AR_Set_BankBranch On AR_Set_BankBranch.BankBranchID = AR_Set_BankAccount.BankBranchID INNER JOIN AR_Set_Bank ON AR_Set_bank.BankID = AR_Set_bankBranch.BankID WHERE AR_Set_bankAccount.Status = 1 and AR_Set_BankBranch.Status = 1 --and AR_Set_bankAccount.CompanyID in @CompanyID AND AR_Set_bankAccount.PeriodID = @PeriodID {0}
Union All
Select tab.BankID,UPPER(tab.BankName) AS BankName, tab.BankBranchID,UPPER(tab.BankBranchName) AS BankBranchName, tab.BankAccountID, tab.BankAccountNumber,UPPER(tab.BankAccountName) AS BankAccountName, SUM(tab.OpeningBalance) TotOpeningBalance From ( Select AR_SET_Bank.BankID, AR_Set_bank.BankName, AR_SET_BankBranch.BankBranchID, AR_Set_bankBranch.BankBranchName, AR_Set_bankAccount.BankAccountID, AR_SET_BankAccount.BankAccountName, AR_SET_BankAccount.BankAccountNumber, IsNull(AR_ReceiptTransactionHeader.Amount, 0) OpeningBalance From AR_Set_bankAccount INNER JOIN AR_Set_bankBranch On AR_Set_bankBranch.BankBranchID = AR_Set_bankAccount.BankBranchID INNER JOIN AR_Set_Bank ON AR_Set_bank.BankID = AR_Set_bankBranch.BankID Left JOIN AR_ReceiptTransactionHeader On AR_Set_bankAccount.PeriodID = AR_ReceiptTransactionHeader.PeriodID And AR_Set_bankAccount.BankAccountID = AR_ReceiptTransactionHeader.BankAccountID And AR_Set_bankAccount.BankBranchID = AR_ReceiptTransactionHeader.CustomerBankBranchID
left JOIN SET_DocumentType ON AR_ReceiptTransactionHeader.CompanyID = SET_DocumentType.CompanyID AND AR_ReceiptTransactionHeader.PeriodID = SET_DocumentType.PeriodID AND AR_ReceiptTransactionHeader.DocumentTypeID = SET_DocumentType.DocumentTypeID {4} {3} {1} WHERE AR_Set_bankAccount.PeriodID = @PeriodID And AR_Set_bankAccount.Status = 1 And AR_ReceiptTransactionHeader.BankAccountID Is Not Null AND AR_ReceiptTransactionHeader.Status = 1 AND AR_ReceiptTransactionHeader.StatusCode = 1 AND AR_ReceiptTransactionHeader.DocumentDate < @FromDate AND (AR_ReceiptTransactionHeader.DocumentTypeID =@DocumentTypeID or @DocumentTypeID is null) And AR_ReceiptTransactionHeader.CompanyID in @CompanyID {0}
UNION ALL
Select AR_SET_Bank.BankID, AR_Set_bank.BankName, AR_SET_BankBranch.BankBranchID, AR_Set_bankBranch.BankBranchName, AR_Set_bankAccount.BankAccountID, AR_SET_BankAccount.BankAccountName, AR_SET_BankAccount.BankAccountNumber, Case When AR_ReceiptBanksDetail.TransactionType = 'Debit' Then IsNull(SUM(AR_ReceiptBanksDetail.Amount), 0) Else IsNull(SUM(AR_ReceiptBanksDetail.Amount), 0) * -1 End As OpeningBalance From AR_ReceiptTransactionHeader INNER Join AR_ReceiptBanksDetail On AR_ReceiptBanksDetail.ReceiptHeaderID = AR_ReceiptTransactionHeader.ReceiptTransactionID and AR_ReceiptBanksDetail.CompanyID = AR_ReceiptTransactionHeader.CompanyID and AR_ReceiptBanksDetail.PeriodID = AR_ReceiptTransactionHeader.PeriodID and AR_ReceiptBanksDetail.FiscalID = AR_ReceiptTransactionHeader.FiscalID and AR_ReceiptBanksDetail.Status = 1 INNER JOIN AR_Set_bankAccount On AR_Set_bankAccount.PeriodID = AR_ReceiptBanksDetail.PeriodID And AR_Set_bankAccount.BankAccountID = AR_ReceiptBanksDetail.BankAccountID and AR_Set_bankAccount.BankBranchID = AR_ReceiptBanksDetail.BankBranchID INNER JOIN AR_Set_BankBranch On AR_Set_BankBranch.BankBranchID = AR_Set_BankAccount.BankBranchID INNER JOIN AR_Set_Bank ON AR_Set_bank.BankID = AR_Set_bankBranch.BankID Inner Join Set_DocumentType On Set_DocumentType.CompanyID = AR_ReceiptTransactionHeader.CompanyID And Set_DocumentType.PeriodID = AR_ReceiptTransactionHeader.PeriodID And Set_DocumentType.DocumentTypeID = AR_ReceiptTransactionHeader.DocumentTypeID inner join SET_OperatingUnit on SET_OperatingUnit.OperatingUnitId = AR_ReceiptTransactionHeader.CompanyID {4} {3} WHERE AR_ReceiptTransactionHeader.CompanyID in @CompanyID AND AR_ReceiptTransactionHeader.PeriodID = @PeriodID AND AR_ReceiptTransactionHeader.DocumentDate < @FromDate And AR_ReceiptTransactionHeader.Status = 1 --AND AR_ReceiptTransactionHeader.StatusCode = 1 And AR_ReceiptBanksDetail.BankAccountID is not null AND (AR_ReceiptTransactionHeader.DocumentTypeID =@DocumentTypeID or @DocumentTypeID is null) {0} {1} group by AR_SET_Bank.BankID, AR_Set_bank.BankName, AR_SET_BankBranch.BankBranchID, AR_Set_bankBranch.BankBranchName, AR_Set_bankAccount.BankAccountID, AR_SET_BankAccount.BankAccountName, AR_SET_BankAccount.BankAccountNumber, AR_ReceiptBanksDetail.TransactionType
UNION ALL
Select AR_SET_Bank.BankID, AR_Set_bank.BankName, AR_SET_BankBranch.BankBranchID, AR_Set_bankBranch.BankBranchName, AR_Set_bankAccount.BankAccountID, AR_SET_BankAccount.BankAccountName, AR_SET_BankAccount.BankAccountNumber, IsNull(AP_PaymentHeader.Amount, 0) * -1 OpeningBalance From AR_Set_bankAccount INNER JOIN AR_Set_bankBranch On AR_Set_bankBranch.BankBranchID = AR_Set_bankAccount.BankBranchID INNER JOIN AR_Set_Bank ON AR_Set_bank.BankID = AR_Set_bankBranch.BankID Left JOIN AP_PaymentHeader On AR_Set_bankAccount.PeriodID = AP_PaymentHeader.PeriodID And AR_Set_bankAccount.BankAccountID = AP_PaymentHeader.BankAccountID
left JOIN SET_DocumentType ON AP_PaymentHeader.CompanyID = SET_DocumentType.CompanyID AND AP_PaymentHeader.PeriodID = SET_DocumentType.PeriodID AND AP_PaymentHeader.DocumentTypeID = SET_DocumentType.DocumentTypeID {4} {3} {2} WHERE AR_Set_bankAccount.PeriodID = @PeriodID And AR_Set_bankAccount.Status = 1 And AP_PaymentHeader.BankAccountID Is Not Null AND AP_PaymentHeader.Status = 1 AND AP_PaymentHeader.StatusCode = 1 And AP_PaymentHeader.DocumentDate < @FromDate And AP_PaymentHeader.CompanyID in @CompanyID AND (AP_PaymentHeader.DocumentTypeID =@DocumentTypeID or @DocumentTypeID is null) {0}
UNION ALL
Select AR_SET_Bank.BankID, AR_Set_bank.BankName, AR_SET_BankBranch.BankBranchID, AR_Set_bankBranch.BankBranchName, AR_Set_bankAccount.BankAccountID, AR_SET_BankAccount.BankAccountName, AR_SET_BankAccount.BankAccountNumber, Case When AP_PaymentBanksDetail.TransactionType = 'Credit' Then IsNull(Sum(AP_PaymentBanksDetail.Amount), 0) * -1 Else IsNull(Sum(AP_PaymentBanksDetail.Amount), 0) End As OpeningBalance From AP_PaymentHeader INNER Join AP_PaymentBanksDetail On AP_PaymentBanksDetail.PaymentHeaderID = AP_PaymentHeader.PaymentID and AP_PaymentBanksDetail.CompanyID = AP_PaymentHeader.CompanyID and AP_PaymentBanksDetail.PeriodID = AP_PaymentHeader.PeriodID and AP_PaymentBanksDetail.FiscalID = AP_PaymentHeader.FiscalID and AP_PaymentBanksDetail.Status = 1 INNER JOIN AR_Set_bankAccount On AR_Set_bankAccount.PeriodID = AP_PaymentBanksDetail.PeriodID And AR_Set_bankAccount.BankAccountID = AP_PaymentBanksDetail.BankAccountID And AR_Set_bankAccount.BankBranchID = AP_PaymentBanksDetail.BankBranchID INNER JOIN AR_Set_bankBranch On AR_Set_bankBranch.BankBranchID = AR_Set_bankAccount.BankBranchID INNER JOIN AR_Set_Bank ON AR_Set_bank.BankID = AR_Set_bankBranch.BankID Inner Join Set_DocumentType On Set_DocumentType.CompanyID = AP_PaymentHeader.CompanyID And Set_DocumentType.PeriodID = AP_PaymentHeader.PeriodID And Set_DocumentType.DocumentTypeID = AP_PaymentHeader.DocumentTypeID inner join SET_OperatingUnit on SET_OperatingUnit.OperatingUnitId = AP_PaymentHeader.CompanyID {4} {3} WHERE AP_PaymentHeader.CompanyID in @CompanyID AND AP_PaymentHeader.PeriodID = @PeriodID And AP_PaymentHeader.Status = 1 --AND AP_PaymentHeader.StatusCode = 1 AND AP_PaymentHeader.DocumentDate < @FromDate and AP_PaymentBanksDetail.BankAccountID is not null AND (AP_PaymentHeader.DocumentTypeID =@DocumentTypeID or @DocumentTypeID is null) {0} {2}
group by AR_SET_Bank.BankID, AR_Set_bank.BankName, AR_SET_BankBranch.BankBranchID, AR_Set_bankBranch.BankBranchName, AR_Set_bankAccount.BankAccountID, AR_SET_BankAccount.BankAccountName, AR_SET_BankAccount.BankAccountNumber, AP_PaymentBanksDetail.TransactionType
)tab Group By tab.BankID, tab.BankName, tab.BankBranchID, tab.BankBranchName, tab.BankAccountID, tab.BankAccountNumber, tab.BankAccountName )FT Group by FT.BankID, FT.BankName, FT.BankBranchID, FT.BankBranchName ,FT.BankAccountID, FT.BankAccountNumber, FT.BankAccountName
Select AR_ReceiptTransactionHeader.PaymentServerOrderNo, AR_SET_Bank.BankID,UPPER( AR_Set_bank.BankName) AS BankName, AR_SET_BankBranch.BankBranchID,UPPER( AR_Set_bankBranch.BankBranchName) AS BankBranchName, AR_Set_bankAccount.BankAccountID, UPPER(AR_SET_BankAccount.BankAccountName) AS BankAccountName, UPPER(AR_SET_BankAccount.BankAccountNumber) AS BankAccountNumber, AR_ReceiptTransactionHeader.DocumentDate, AR_ReceiptTransactionHeader.DocumentNo,uPPER(AR_ReceiptTransactionHeader.Comments) as ItemName, AR_ReceiptTransactionHeader.Amount - ISNULL( ( Select SUM(Amount) from AR_ReceiptAccountsDetail rad where rad.TransactionType = 'Debit' and rad.ReceiptAccountID = AR_ReceiptAccountsDetail.ReceiptAccountID and rad.ReceiptHeaderID = AR_ReceiptAccountsDetail.ReceiptHeaderID ), 0) as CurrentBalanceDebit, 0 as CurrentBalanceCredit,UPPER(Set_DocumentType.DocumentType) AS DocumentType,Set_DocumentType.DocumentTypeID ,case AR_ReceiptTransactionHeader.StatusCode when 1 then 1 else 0 end as Unposted ,SET_OperatingUnit.OperatingUnitName as UnitName ,AR_ReceiptTransactionHeader.CreateDate,AR_ReceiptTransactionHeader.DocumentTypeID From AR_ReceiptTransactionHeader LEFT JOIN AR_Set_bankAccount On AR_Set_bankAccount.PeriodID = AR_ReceiptTransactionHeader.PeriodID And AR_Set_bankAccount.BankAccountID = AR_ReceiptTransactionHeader.BankAccountID And AR_Set_bankAccount.BankBranchID = AR_ReceiptTransactionHeader.CustomerBankBranchID And AR_Set_bankAccount.Status = 1 INNER JOIN AR_Set_bankBranch On AR_Set_bankBranch.BankBranchID = AR_Set_bankAccount.BankBranchID INNER JOIN AR_Set_Bank ON AR_Set_bank.BankID = AR_Set_bankBranch.BankID Inner Join Set_DocumentType On Set_DocumentType.CompanyID = AR_ReceiptTransactionHeader.CompanyID And Set_DocumentType.PeriodID = AR_ReceiptTransactionHeader.PeriodID And Set_DocumentType.DocumentTypeID = AR_ReceiptTransactionHeader.DocumentTypeID {4} {3} Left Join AR_ReceiptAccountsDetail on AR_ReceiptAccountsDetail.ReceiptHeaderID = AR_ReceiptTransactionHeader.ReceiptTransactionID and AR_ReceiptAccountsDetail.CompanyID = AR_ReceiptTransactionHeader.CompanyID and AR_ReceiptAccountsDetail.PeriodID = AR_ReceiptTransactionHeader.PeriodID inner join SET_OperatingUnit on SET_OperatingUnit.OperatingUnitId = AR_ReceiptTransactionHeader.CompanyID WHERE AR_ReceiptTransactionHeader.CompanyID in @CompanyID AND AR_ReceiptTransactionHeader.PeriodID = @PeriodID AND AR_ReceiptTransactionHeader.DocumentDate Between @FromDate AND @DateTo And AR_ReceiptTransactionHeader.Status = 1 --AND AR_ReceiptTransactionHeader.StatusCode = 1 AND AR_ReceiptTransactionHeader.BankAccountID is not null AND (AR_ReceiptTransactionHeader.DocumentTypeID =@DocumentTypeID or @DocumentTypeID is null) {0} {1}
UNION ALL
Select Case When AR_ReceiptTransactionHeader.PaymentServerOrderNo IS NULL Then AR_ReceiptBanksDetail.InstrumentNo Else AR_ReceiptTransactionHeader.PaymentServerOrderNo End As PaymentServerOrderNo, AR_SET_Bank.BankID, AR_Set_bank.BankName, AR_SET_BankBranch.BankBranchID, AR_Set_bankBranch.BankBranchName, AR_Set_bankAccount.BankAccountID, AR_SET_BankAccount.BankAccountName, AR_SET_BankAccount.BankAccountNumber, AR_ReceiptTransactionHeader.DocumentDate, AR_ReceiptTransactionHeader.DocumentNo, AR_ReceiptBanksDetail.Comments as ItemName, Case When AR_ReceiptBanksDetail.TransactionType = 'Debit' Then sum(AR_ReceiptBanksDetail.Amount) Else 0 End As CurrentBalanceDebit, Case When AR_ReceiptBanksDetail.TransactionType = 'Credit' Then sum(AR_ReceiptBanksDetail.Amount) Else 0 End As CurrentBalanceCredit, Set_DocumentType.DocumentType,Set_DocumentType.DocumentTypeID ,case AR_ReceiptTransactionHeader.StatusCode when 1 then 1 else 0 end as Unposted ,SET_OperatingUnit.OperatingUnitName as UnitName ,AR_ReceiptTransactionHeader.CreateDate,AR_ReceiptTransactionHeader.DocumentTypeID From AR_ReceiptTransactionHeader INNER Join AR_ReceiptBanksDetail On AR_ReceiptBanksDetail.ReceiptHeaderID = AR_ReceiptTransactionHeader.ReceiptTransactionID and AR_ReceiptBanksDetail.CompanyID = AR_ReceiptTransactionHeader.CompanyID and AR_ReceiptBanksDetail.PeriodID = AR_ReceiptTransactionHeader.PeriodID and AR_ReceiptBanksDetail.FiscalID = AR_ReceiptTransactionHeader.FiscalID and AR_ReceiptBanksDetail.Status = 1 INNER JOIN AR_Set_bankAccount On AR_Set_bankAccount.PeriodID = AR_ReceiptBanksDetail.PeriodID And AR_Set_bankAccount.BankAccountID = AR_ReceiptBanksDetail.BankAccountID and AR_Set_bankAccount.BankBranchID = AR_ReceiptBanksDetail.BankBranchID INNER JOIN AR_Set_BankBranch On AR_Set_BankBranch.BankBranchID = AR_Set_BankAccount.BankBranchID INNER JOIN AR_Set_Bank ON AR_Set_bank.BankID = AR_Set_bankBranch.BankID Inner Join Set_DocumentType On Set_DocumentType.CompanyID = AR_ReceiptTransactionHeader.CompanyID And Set_DocumentType.PeriodID = AR_ReceiptTransactionHeader.PeriodID And Set_DocumentType.DocumentTypeID = AR_ReceiptTransactionHeader.DocumentTypeID inner join SET_OperatingUnit on SET_OperatingUnit.OperatingUnitId = AR_ReceiptTransactionHeader.CompanyID {4} {3} WHERE AR_ReceiptTransactionHeader.CompanyID in @CompanyID AND AR_ReceiptTransactionHeader.PeriodID = @PeriodID AND AR_ReceiptTransactionHeader.DocumentDate Between @FromDate AND @DateTo And AR_ReceiptTransactionHeader.Status = 1 --AND AR_ReceiptTransactionHeader.StatusCode = 1 And AR_ReceiptBanksDetail.BankAccountID is not null AND (AR_ReceiptTransactionHeader.DocumentTypeID =@DocumentTypeID or @DocumentTypeID is null) {0} {1} group by AR_ReceiptTransactionHeader.PaymentServerOrderNo, AR_SET_Bank.BankID, AR_Set_bank.BankName, AR_SET_BankBranch.BankBranchID, AR_Set_bankBranch.BankBranchName, AR_Set_bankAccount.BankAccountID, AR_SET_BankAccount.BankAccountName, AR_SET_BankAccount.BankAccountNumber, AR_ReceiptTransactionHeader.DocumentDate, AR_ReceiptTransactionHeader.DocumentNo, AR_ReceiptBanksDetail.Comments, AR_ReceiptBanksDetail.TransactionType,Set_DocumentType.DocumentType,Set_DocumentType.DocumentTypeID,AR_ReceiptBanksDetail.ReceiptBankID, AR_ReceiptBanksDetail.InstrumentNo ,AR_ReceiptTransactionHeader.StatusCode,SET_OperatingUnit.OperatingUnitName ,AR_ReceiptTransactionHeader.CreateDate,AR_ReceiptTransactionHeader.DocumentTypeID UNION ALL
Select AP_PaymentHeader.PaymentServerOrderNo, AR_SET_Bank.BankID, AR_Set_bank.BankName, AR_SET_BankBranch.BankBranchID, AR_Set_bankBranch.BankBranchName, AR_Set_bankAccount.BankAccountID, AR_SET_BankAccount.BankAccountName, AR_SET_BankAccount.BankAccountNumber, AP_PaymentHeader.DocumentDate, AP_PaymentHeader.DocumentNo, AP_PaymentHeader.Comments as ItemName, IsNull(case when AP_Payment_AccountsDetail.TransactionType = 'Debit' then AP_PaymentHeader.Amount - IsNull(sum(AP_Payment_AccountsDetail.Amount), 0) when AP_Payment_AccountsDetail.TransactionType = 'Credit' then Abs(AP_PaymentHeader.Amount) end, 0) as CurrentBalanceDebit, case when AP_Payment_AccountsDetail.TransactionType = 'Credit' then AP_PaymentHeader.Amount + IsNull(sum(AP_Payment_AccountsDetail.Amount), 0) when AP_Payment_AccountsDetail.TransactionType = 'Debit' then AP_PaymentHeader.Amount else AP_PaymentHeader.Amount end as CurrentBalanceCredit, Set_DocumentType.DocumentType ,Set_DocumentType.DocumentTypeID ,case AP_PaymentHeader.StatusCode when 1 then 1 else 0 end as Unposted ,SET_OperatingUnit.OperatingUnitName as UnitName ,AP_PaymentHeader .CreateDate,AP_PaymentHeader.DocumentTypeID From AP_PaymentHeader left join AP_Payment_AccountsDetail on AP_Payment_AccountsDetail.PaymentHeaderID = AP_PaymentHeader.PaymentID and AP_Payment_AccountsDetail.CompanyId = AP_PaymentHeader.CompanyId and AP_Payment_AccountsDetail.periodID = AP_PaymentHeader.periodID and AP_Payment_AccountsDetail.FiscalID = AP_PaymentHeader.FiscalID INNER JOIN AR_Set_bankAccount On AR_Set_bankAccount.PeriodID = AP_PaymentHeader.PeriodID And AR_Set_bankAccount.BankAccountID = AP_PaymentHeader.BankAccountID INNER JOIN AR_Set_bankBranch On AR_Set_bankBranch.BankBranchID = AR_Set_bankAccount.BankBranchID INNER JOIN AR_Set_Bank ON AR_Set_bank.BankID = AR_Set_bankBranch.BankID Inner Join Set_DocumentType On Set_DocumentType.CompanyID = AP_PaymentHeader.CompanyID And Set_DocumentType.PeriodID = AP_PaymentHeader.PeriodID And Set_DocumentType.DocumentTypeID = AP_PaymentHeader.DocumentTypeID inner join SET_OperatingUnit on SET_OperatingUnit.OperatingUnitId = AP_PaymentHeader.CompanyID {4} {3} WHERE AP_PaymentHeader.CompanyID in @CompanyID AND AP_PaymentHeader.PeriodID = @PeriodID And AP_PaymentHeader.Status = 1 -- AND AP_PaymentHeader.StatusCode = 1 AND AP_PaymentHeader.DocumentDate Between @FromDate AND @DateTo AND AP_PaymentHeader.BankAccountID is not null AND (AP_PaymentHeader.DocumentTypeID =@DocumentTypeID or @DocumentTypeID is null) {0} {2} group by AP_PaymentHeader.PaymentServerOrderNo, AR_SET_Bank.BankID, AR_Set_bank.BankName, AR_SET_BankBranch.BankBranchID, AR_Set_bankBranch.BankBranchName, AR_Set_bankAccount.BankAccountID, AR_SET_BankAccount.BankAccountName, AR_SET_BankAccount.BankAccountNumber, AP_PaymentHeader.DocumentDate, AP_PaymentHeader.DocumentNo, AP_PaymentHeader.Comments, AP_PaymentHeader.Amount, AP_Payment_AccountsDetail.Amount, AP_Payment_AccountsDetail.TransactionType, Set_DocumentType.DocumentType ,Set_DocumentType.DocumentTypeID ,AP_PaymentHeader.StatusCode ,SET_OperatingUnit.OperatingUnitName ,AP_PaymentHeader .CreateDate,AP_PaymentHeader.DocumentTypeID
UNION ALL
Select Case When AP_PaymentHeader.PaymentServerOrderNo IS NULL Then AP_PaymentBanksDetail.InstrumentNo Else AP_PaymentHeader.PaymentServerOrderNo End As PaymentServerOrderNo, AR_Set_bank.BankID, AR_Set_bank.BankName, AP_PaymentBanksDetail.BankBranchID, AR_Set_bankBranch.BankBranchName, AP_PaymentBanksDetail.BankAccountID, AR_SET_BankAccount.BankAccountName, AR_SET_BankAccount.BankAccountNumber, AP_PaymentHeader.DocumentDate, AP_PaymentHeader.DocumentNo, AP_PaymentBanksDetail.Comments as ItemName, Case When AP_PaymentBanksDetail.TransactionType = 'Debit' Then AP_PaymentBanksDetail.Amount Else 0 End as CurrentBalanceDebit, Case When AP_PaymentBanksDetail.TransactionType = 'Credit' Then AP_PaymentBanksDetail.Amount Else 0 End as CurrentBalanceCredit, Set_DocumentType.DocumentType ,Set_DocumentType.DocumentTypeID ,case AP_PaymentHeader.StatusCode when 1 then 1 else 0 end as Unposted ,SET_OperatingUnit.OperatingUnitName as UnitName ,AP_PaymentHeader .CreateDate,AP_PaymentHeader.DocumentTypeID From AP_PaymentHeader INNER Join AP_PaymentBanksDetail On AP_PaymentBanksDetail.PaymentHeaderID = AP_PaymentHeader.PaymentID and AP_PaymentBanksDetail.CompanyID = AP_PaymentHeader.CompanyID and AP_PaymentBanksDetail.PeriodID = AP_PaymentHeader.PeriodID and AP_PaymentBanksDetail.FiscalID = AP_PaymentHeader.FiscalID and AP_PaymentBanksDetail.Status = 1 INNER JOIN AR_Set_bankAccount On AR_Set_bankAccount.PeriodID = AP_PaymentBanksDetail.PeriodID And AR_Set_bankAccount.BankAccountID = AP_PaymentBanksDetail.BankAccountID And AR_Set_bankAccount.BankBranchID = AP_PaymentBanksDetail.BankBranchID INNER JOIN AR_Set_bankBranch On AR_Set_bankBranch.BankBranchID = AR_Set_bankAccount.BankBranchID INNER JOIN AR_Set_Bank ON AR_Set_bank.BankID = AR_Set_bankBranch.BankID Inner Join Set_DocumentType On Set_DocumentType.CompanyID = AP_PaymentHeader.CompanyID And Set_DocumentType.PeriodID = AP_PaymentHeader.PeriodID And Set_DocumentType.DocumentTypeID = AP_PaymentHeader.DocumentTypeID inner join SET_OperatingUnit on SET_OperatingUnit.OperatingUnitId = AP_PaymentHeader.CompanyID {4} {3} WHERE AP_PaymentHeader.CompanyID in @CompanyID AND AP_PaymentHeader.PeriodID = @PeriodID And AP_PaymentHeader.Status = 1 --AND AP_PaymentHeader.StatusCode = 1 AND AP_PaymentHeader.DocumentDate Between @FromDate AND @DateTo and AP_PaymentBanksDetail.BankAccountID is not null AND (AP_PaymentHeader.DocumentTypeID =@DocumentTypeID or @DocumentTypeID is null) {0} {2}

select FT.BankBranchID, FT.BankBranchName, FT.BankAccountID, FT.BankAccountNumber , SUM(FT.OpeningBalance) OpeningBalance,BankName from (
Select Distinct AR_SET_BankBranch.BankBranchID,UPPER(AR_Set_bankBranch.BankBranchName) AS BankBranchName , AR_Set_bankAccount.BankAccountID,UPPER(AR_Set_bankAccount.BankAccountNumber) AS BankAccountNumber, 0 As OpeningBalance ,upper(AR_SET_Bank.BankName) as BankName From AR_Set_bankAccount INNER JOIN AR_Set_BankBranch On AR_Set_BankBranch.BankBranchID = AR_Set_BankAccount.BankBranchID inner join AR_SET_Bank on AR_SET_Bank.bankid = AR_Set_BankBranch.bankid WHERE AR_Set_bankAccount.Status = 1 and AR_Set_BankBranch.Status = 1 AND AR_Set_bankAccount.PeriodID = @PeriodID {4} {8}
Union All
Select Distinct tab.BankBranchID,UPPER(tab.BankBranchName) AS BankBranchName, tab.BankAccountID, UPPER( tab.BankAccountNumber) AS BankAccountNumber, SUM(tab.OpeningBalance) OpeningBalance,upper(BankName) as BankName From ( Select AR_SET_BankBranch.BankBranchID, AR_Set_bankBranch.BankBranchName, AR_Set_bankAccount.BankAccountID, AR_SET_BankAccount.BankAccountNumber, IsNull(AP_PaymentHeader.Amount, 0) * -1 OpeningBalance ,AR_SET_Bank.BankName From AR_Set_bankAccount INNER JOIN AR_Set_bankBranch On AR_Set_bankBranch.BankBranchID = AR_Set_bankAccount.BankBranchID
inner join AR_SET_Bank on AR_SET_Bank.bankid = AR_Set_BankBranch.bankid Left JOIN AP_PaymentHeader On AR_Set_bankAccount.PeriodID = AP_PaymentHeader.PeriodID And AR_Set_bankAccount.BankAccountID = AP_PaymentHeader.BankAccountID AND AP_PaymentHeader.Status = 1 AND AP_PaymentHeader.StatusCode = 1 left JOIN SET_DocumentType ON AP_PaymentHeader.CompanyID = SET_DocumentType.CompanyID AND AP_PaymentHeader.PeriodID = SET_DocumentType.PeriodID AND AP_PaymentHeader.DocumentTypeID = SET_DocumentType.DocumentTypeID
{6} {5} {1} WHERE AR_Set_bankAccount.PeriodID = @PeriodID And AR_Set_bankAccount.Status = 1 and AP_PaymentHeader.DocumentDate < @FromDate and AP_PaymentHeader.CompanyID in @CompanyID AND AP_PaymentHeader.ActivityDate IS NOT NULL AND (AP_PaymentHeader.DocumentTypeID =@DocumentTypeID or @DocumentTypeID is null) {4} {8}
UNION ALL
Select AR_SET_BankBranch.BankBranchID, AR_Set_bankBranch.BankBranchName, AR_Set_bankAccount.BankAccountID, AR_SET_BankAccount.BankAccountNumber, Case When AR_ReceiptBanksDetail.TransactionType = 'Debit' Then IsNull(SUM(AR_ReceiptBanksDetail.Amount), 0) Else IsNull(SUM(AR_ReceiptBanksDetail.Amount), 0) * -1 End As OpeningBalance ,AR_SET_Bank.BankName From AR_ReceiptTransactionHeader INNER JOIN AR_ReceiptBanksDetail ON AR_ReceiptBanksDetail.CompanyID = AR_ReceiptTransactionHeader.CompanyID AND AR_ReceiptBanksDetail.PeriodID = AR_ReceiptTransactionHeader.PeriodID AND AR_ReceiptBanksDetail.ReceiptHeaderID = AR_ReceiptTransactionHeader.ReceiptTransactionID AND AR_ReceiptBanksDetail.Status=1 INNER JOIN AR_Set_bankAccount On AR_Set_bankAccount.PeriodID = AR_ReceiptBanksDetail.PeriodID And AR_Set_bankAccount.BankAccountID = AR_ReceiptBanksDetail.BankAccountID and AR_Set_bankAccount.BankBranchID = AR_ReceiptBanksDetail.BankBranchID INNER JOIN AR_Set_BankBranch On AR_Set_BankBranch.BankBranchID = AR_Set_BankAccount.BankBranchID inner join AR_SET_Bank on AR_SET_Bank.bankid = AR_Set_BankBranch.bankid Inner Join Set_DocumentType On Set_DocumentType.CompanyID = AR_ReceiptTransactionHeader.CompanyID And Set_DocumentType.PeriodID = AR_ReceiptTransactionHeader.PeriodID And Set_DocumentType.DocumentTypeID = AR_ReceiptTransactionHeader.DocumentTypeID INNER JOIN SET_OperatingUnit on SET_OperatingUnit.OperatingUnitId = AR_ReceiptTransactionHeader.CompanyID {6} {5} WHERE AR_ReceiptTransactionHeader.CompanyID in @CompanyID AND AR_ReceiptTransactionHeader.PeriodID = @PeriodID And AR_ReceiptTransactionHeader.Status = 1 AND (AR_ReceiptTransactionHeader.DocumentTypeID =@DocumentTypeID or @DocumentTypeID is null) And AR_ReceiptTransactionHeader.StatusCode = 1 AND AR_ReceiptTransactionHeader.ActivityDate IS NOT NULL {4} {0}
group by AR_SET_BankBranch.BankBranchID,AR_Set_BankBranch.BankBranchName,AR_Set_bankAccount.BankAccountID,AR_Set_bankAccount.BankAccountNumber ,AR_ReceiptBanksDetail.TransactionType,AR_SET_Bank.BankName
UNION ALL
Select AR_SET_BankBranch.BankBranchID, AR_Set_bankBranch.BankBranchName, AR_Set_bankAccount.BankAccountID, AR_SET_BankAccount.BankAccountNumber, Case When AP_PaymentBanksDetail.TransactionType = 'Credit' Then IsNull(SUM(AP_PaymentBanksDetail.Amount), 0) * -1 Else IsNull(SUM(AP_PaymentBanksDetail.Amount), 0) End As OpeningBalance ,AR_SET_Bank.BankName From AP_PaymentHeader INNER JOIN AP_PaymentBanksDetail ON AP_PaymentBanksDetail.CompanyID = AP_PaymentHeader.CompanyID AND AP_PaymentBanksDetail.PeriodID = AP_PaymentHeader.PeriodID AND AP_PaymentBanksDetail.PaymentHeaderID = AP_PaymentHeader.PaymentID AND AP_PaymentBanksDetail.Status=1 INNER JOIN AR_Set_bankAccount On AR_Set_bankAccount.PeriodID = AP_PaymentBanksDetail.PeriodID And AR_Set_bankAccount.BankAccountID = AP_PaymentBanksDetail.BankAccountID and AR_Set_bankAccount.BankBranchID = AP_PaymentBanksDetail.BankBranchID INNER JOIN AR_Set_BankBranch On AR_Set_BankBranch.BankBranchID = AR_Set_BankAccount.BankBranchID inner join AR_SET_Bank on AR_SET_Bank.bankid = AR_Set_BankBranch.bankid Inner Join Set_DocumentType On Set_DocumentType.CompanyID = AP_PaymentHeader.CompanyID And Set_DocumentType.PeriodID = AP_PaymentHeader.PeriodID And Set_DocumentType.DocumentTypeID = AP_PaymentHeader.DocumentTypeID INNER JOIN SET_OperatingUnit on SET_OperatingUnit.OperatingUnitId = AP_PaymentHeader.CompanyID {6} {5} WHERE AP_PaymentHeader.CompanyID in @CompanyID AND AP_PaymentHeader.PeriodID = @PeriodID And AP_PaymentHeader.Status = 1 AND AP_PaymentHeader.StatusCode = 1 AND (AP_PaymentHeader.DocumentTypeID =@DocumentTypeID or @DocumentTypeID is null) AND AP_PaymentHeader.ActivityDate IS NOT NULL {4} {1}
group by AR_SET_BankBranch.BankBranchID, AR_Set_bankBranch.BankBranchName, AR_Set_bankAccount.BankAccountID, AR_SET_BankAccount.BankAccountNumber, AP_PaymentBanksDetail.TransactionType ,AR_SET_Bank.BankName )tab Group By tab.BankBranchID, tab.BankBranchName, tab.BankAccountID, tab.BankAccountNumber ,bankName )FT Group By FT.BankBranchID, FT.BankBranchName, FT.BankAccountID, FT.BankAccountNumber ,bankName
