select 1 as SerialNo,'Balance As Per Bank Ledger' AS Description, ISNULL(sum(ResultValue),0) as Balance from ( Select isnull(sum(AR_ReceiptTransactionHeader.Amount), 0) As ResultValue, AR_Set_bank.BankName, AR_Set_bankAccount.BankAccountNumber, AR_Set_bankBranch.BankBranchName From AR_Set_bank Inner Join AR_Set_bankBranch ON AR_Set_bankBranch.BankID = AR_Set_bank.BankID AND AR_Set_bankBranch.Status = 1 Inner Join AR_Set_bankAccount On AR_Set_bankBranch.BankBranchID = AR_Set_bankAccount.BankBranchID And AR_Set_bankAccount.Status = 1 Inner Join AR_ReceiptTransactionHeader ON AR_ReceiptTransactionHeader.BankAccountID = AR_Set_bankAccount.BankAccountID And AR_Set_bankAccount.CompanyId = AR_ReceiptTransactionHeader.CompanyId And AR_Set_bankAccount.PeriodID = AR_ReceiptTransactionHeader.PeriodID And AR_ReceiptTransactionHeader.Status = 1 AND AR_ReceiptTransactionHeader.StatusCode = 1 INNER JOIN SET_DocumentType ON AR_ReceiptTransactionHeader.CompanyID = SET_DocumentType.CompanyID AND AR_ReceiptTransactionHeader.PeriodID = SET_DocumentType.PeriodID AND AR_ReceiptTransactionHeader.DocumentTypeID = SET_DocumentType.DocumentTypeID -- INNER JOIN UsersInDocumentType ON UsersInDocumentType.CompanyID = SET_DocumentType.CompanyID --AND UsersInDocumentType.DocumentTypeID = SET_DocumentType.DocumentTypeID AND UsersInDocumentType.UserID = @UserID where AR_Set_bankAccount.CompanyID in @CompanyID And AR_Set_bankAccount.PeriodID = @PeriodID And AR_Set_bank.status = 1 and AR_ReceiptTransactionHeader.DocumentNo is not null AND AR_ReceiptTransactionHeader.DocumentDate <= @ToDate AND AR_ReceiptTransactionHeader.BankAccountID is not null --and isnull(AR_SET_BankAccount.ShowInBankStatusReport, 0) = 1 {0} {2}
group by AR_Set_bankAccount.BankAccountNumber, AR_Set_bank.BankName, AR_Set_bankBranch.BankBranchName
UNION ALL
