WHERE AR_ReceiptTransactionHeader.CompanyID = @CompanyID AND AR_ReceiptTransactionHeader.PeriodID = @PeriodID And AR_ReceiptTransactionHeader.Status = 1 AND AR_ReceiptTransactionHeader.StatusCode = 1 AND AR_ReceiptTransactionHeader.BankAccountID is not null
AND AR_ReceiptTransactionHeader.DocumentDate <= @ToDate {0} {2}
UNION ALL
Select AR_Set_bankAccount.BankAccountID, AP_PaymentHeader.DocumentDate, AP_PaymentHeader.DocumentNo, 0 as ReceiptAmount, AP_PaymentHeader.Amount as PaymentAmount, Set_DocumentType.DocumentType, AP_PaymentHeader.PaymentServerOrderNo As InstrumentNo, AP_PaymentHeader.AntiCipatedClearingDate as InstrumentDate, IsNull(AP_PaymentHeader.Comments, '') + IsNull(AP_PaymentHeader.ReversalComments, '') As Comments, AR_Set_bankAccount.BankAccountNumber ,'' as BankID , case AP_PaymentHeader.StatusCode when 1 then 1 else 0 end as unPosted ,AP_PaymentHeader.ActivityDate,AP_PaymentHeader.IssueDate From AP_PaymentHeader INNER JOIN AR_Set_bankAccount On AR_Set_bankAccount.CompanyId = AP_PaymentHeader.CompanyId And AR_Set_bankAccount.PeriodID = AP_PaymentHeader.PeriodID And AR_Set_bankAccount.BankAccountID = AP_PaymentHeader.BankAccountID INNER JOIN AR_Set_BankBranch On AR_Set_BankBranch.BankBranchID = AR_Set_BankAccount.BankBranchID Inner Join Set_DocumentType On Set_DocumentType.CompanyID = AP_PaymentHeader.CompanyID And Set_DocumentType.PeriodID = AP_PaymentHeader.PeriodID And Set_DocumentType.DocumentTypeID = AP_PaymentHeader.DocumentTypeID INNER JOIN UsersInDocumentType ON UsersInDocumentType.CompanyID = SET_DocumentType.CompanyID AND UsersInDocumentType.DocumentTypeID = SET_DocumentType.DocumentTypeID -- AND UsersInDocumentType.UserID = @UserID
WHERE AP_PaymentHeader.CompanyID = @CompanyID AND AP_PaymentHeader.PeriodID = @PeriodID And AP_PaymentHeader.Status = 1 AND AP_PaymentHeader.StatusCode = 1 AND AP_PaymentHeader.BankAccountID is not null AND (AP_PaymentHeader.DocumentDate <= @ToDate ) {1} {2}
UNION ALL
Select AR_Set_bankAccount.BankAccountID, AR_ReceiptTransactionHeader.DocumentDate, AR_ReceiptTransactionHeader.DocumentNo, (Case when AR_ReceiptBanksDetail.TransactionType = 'Debit' then AR_ReceiptBanksDetail.Amount else 0 end) as ReceiptAmount, (Case when AR_ReceiptBanksDetail.TransactionType = 'Credit' then AR_ReceiptBanksDetail.Amount else 0 end) as PaymentAmount, Set_DocumentType.DocumentType, AR_ReceiptBanksDetail.InstrumentNo,AR_ReceiptBanksDetail.InstrumentDate, AR_ReceiptBanksDetail.Comments, AR_Set_bankAccount.BankAccountNumber ,AR_ReceiptBanksDetail.ReceiptBankID as BankID , case AR_ReceiptTransactionHeader.StatusCode when 1 then 1 else 0 end as unPosted ,AR_ReceiptTransactionHeader.ActivityDate,AR_ReceiptTransactionHeader.IssueDate From AR_ReceiptTransactionHeader INNER JOIN AR_ReceiptBanksDetail ON AR_ReceiptBanksDetail.CompanyID = AR_ReceiptTransactionHeader.CompanyID AND AR_ReceiptBanksDetail.PeriodID = AR_ReceiptTransactionHeader.PeriodID AND AR_ReceiptBanksDetail.ReceiptHeaderID = AR_ReceiptTransactionHeader.ReceiptTransactionID AND AR_ReceiptBanksDetail.Status=1 INNER JOIN AR_Set_bankAccount On AR_Set_bankAccount.CompanyId = AR_ReceiptBanksDetail.CompanyId And AR_Set_bankAccount.PeriodID = AR_ReceiptBanksDetail.PeriodID And AR_Set_bankAccount.BankAccountID = AR_ReceiptBanksDetail.BankAccountID INNER JOIN AR_Set_BankBranch On AR_Set_BankBranch.BankBranchID = AR_Set_BankAccount.BankBranchID Inner Join Set_DocumentType On Set_DocumentType.CompanyID = AR_ReceiptTransactionHeader.CompanyID And Set_DocumentType.PeriodID = AR_ReceiptTransactionHeader.PeriodID And Set_DocumentType.DocumentTypeID = AR_ReceiptTransactionHeader.DocumentTypeID -- INNER JOIN UsersInDocumentType ON UsersInDocumentType.CompanyID = SET_DocumentType.CompanyID --AND UsersInDocumentType.DocumentTypeID = SET_DocumentType.DocumentTypeID -- AND UsersInDocumentType.UserID = @UserID
WHERE AR_ReceiptTransactionHeader.CompanyID = @CompanyID AND AR_ReceiptTransactionHeader.PeriodID = @PeriodID And AR_ReceiptTransactionHeader.Status = 1 AND AR_ReceiptTransactionHeader.StatusCode = 1
AND AR_ReceiptTransactionHeader.DocumentDate <= @ToDate {0} {2}
UNION ALL
Select AR_Set_bankAccount.BankAccountID, AP_PaymentHeader.DocumentDate, AP_PaymentHeader.DocumentNo, (Case when AP_PaymentBanksDetail.TransactionType = 'Debit' then AP_PaymentBanksDetail.Amount else 0 end) as ReceiptAmount, (Case when AP_PaymentBanksDetail.TransactionType = 'Credit' then AP_PaymentBanksDetail.Amount else 0 end) as PaymentAmount, Set_DocumentType.DocumentType, AP_PaymentBanksDetail.InstrumentNo,AP_PaymentBanksDetail.InstrumentDate, AP_PaymentBanksDetail.Comments, AR_Set_bankAccount.BankAccountNumber ,AP_PaymentBanksDetail.PaymentBankID as BankID , case AP_PaymentHeader.StatusCode when 1 then 1 else 0 end as unPosted ,AP_PaymentHeader.ActivityDate,AP_PaymentHeader.IssueDate From AP_PaymentHeader INNER JOIN AP_PaymentBanksDetail ON AP_PaymentBanksDetail.CompanyID = AP_PaymentHeader.CompanyID AND AP_PaymentBanksDetail.PeriodID = AP_PaymentHeader.PeriodID AND AP_PaymentBanksDetail.PaymentHeaderID = AP_PaymentHeader.PaymentID AND AP_PaymentBanksDetail.Status=1 INNER JOIN AR_Set_bankAccount On AR_Set_bankAccount.CompanyId = AP_PaymentBanksDetail.CompanyId And AR_Set_bankAccount.PeriodID = AP_PaymentBanksDetail.PeriodID And AR_Set_bankAccount.BankAccountID = AP_PaymentBanksDetail.BankAccountID INNER JOIN AR_Set_BankBranch On AR_Set_BankBranch.BankBranchID = AR_Set_BankAccount.BankBranchID Inner Join Set_DocumentType On Set_DocumentType.CompanyID = AP_PaymentHeader.CompanyID And Set_DocumentType.PeriodID = AP_PaymentHeader.PeriodID And Set_DocumentType.DocumentTypeID = AP_PaymentHeader.DocumentTypeID -- INNER JOIN UsersInDocumentType ON UsersInDocumentType.CompanyID = SET_DocumentType.CompanyID --AND UsersInDocumentType.DocumentTypeID = SET_DocumentType.DocumentTypeID --AND UsersInDocumentType.UserID = @UserID
WHERE AP_PaymentHeader.CompanyID = @CompanyID AND AP_PaymentHeader.PeriodID = @PeriodID And AP_PaymentHeader.Status = 1 AND AP_PaymentHeader.StatusCode = 1
-- AND AP_PaymentHeader.ActivityDate is null AND AP_PaymentHeader.IssueDate is null AND (AP_PaymentHeader.DocumentDate <= @ToDate) {1} {2}
)tab2
Group By tab2.DocumentType, tab2.BankAccountID, tab2.DocumentNo, tab2.DocumentDate, tab2.InstrumentNo, tab2.Comments, tab2.BankAccountNumber,tab2.BankID,unPosted ,ActivityDate,IssueDate,InstrumentDate order by tab2.DocumentDate
